#!/usr/bin/env bash
set -euo pipefail

root_dir="$(git rev-parse --show-toplevel)"
cd "${root_dir}"

./scripts/validate/pinned-toolchain.sh
./scripts/validate/pages-config.sh

cd packages/pwa
bun install --frozen-lockfile

cd "${root_dir}"
task build:pwa

test -f packages/pwa/dist/_headers
test -f packages/pwa/dist/_redirects

# The `fy-render` sandbox shell, its two library bundles and the `html` shell are GENERATED by
# `bun run build:fy-render-shell`, which the package build chains ahead of Vite.
# Assert they reached `dist` rather than trusting that chain: if generation ever
# stops running, the deploy ships a 404 shell, every diagram and animation
# degrades silently to its source text, and nothing else in this pipeline fails.
for asset in fy-render-sandbox.html fy-render-mermaid.js fy-render-lottie.js fy-render-html.html; do
  test -s "packages/pwa/dist/${asset}" || {
    echo "❌ packages/pwa/dist/${asset} is missing or empty; the fy-render shell was not generated" >&2
    exit 1
  }
done
# The published model catalog (docs/model-catalog.md): every paired daemon follows its model lists
# from these two files, checked against the signed release list below.
for asset in catalog/models.json catalog/version.json; do
  test -s "packages/pwa/dist/${asset}" || {
    echo "❌ packages/pwa/dist/${asset} is missing or empty; the model catalog was not written" >&2
    exit 1
  }
done
# The signed-release files (docs/pwa-release-signing.md). The build always writes the UNSIGNED
# marker; only scripts/ci/sign-pwa-release.sh, holding the key, replaces it.
for asset in sw.verified.js release-manifest.json release-manifest.sig; do
  test -s "packages/pwa/dist/${asset}" || {
    echo "❌ packages/pwa/dist/${asset} is missing or empty; the release step did not run" >&2
    exit 1
  }
done
listed="$(jq -r '.files | keys[]' packages/pwa/dist/release-manifest.json | sort)"
present="$(cd packages/pwa/dist && find . -type f ! -name _headers ! -name _redirects ! -name 'release-manifest.*' | sed 's|^\./||' | sort)"
[[ ${listed} == "${present}" ]] || {
  echo "❌ packages/pwa/dist/release-manifest.json does not list exactly the files in dist" >&2
  diff <(printf '%s\n' "${listed}") <(printf '%s\n' "${present}") >&2 || true
  exit 1
}
# The static pages name the release they were built from (`vite.config.ts` stamps VERSION in). A
# placeholder that survived the build would show a newcomer `v%FY_RELEASE_VERSION%`.
for page in index.html get-started/index.html; do
  if rg -qF '%FY_RELEASE_VERSION%' "packages/pwa/dist/${page}" || ! rg -qF "v$(cat VERSION)" "packages/pwa/dist/${page}"; then
    echo "❌ packages/pwa/dist/${page} does not name release v$(cat VERSION)" >&2
    exit 1
  fi
done
# Cloudflare Pages refuses to deploy ANY file over 25 MiB, and that refusal only shows up in the
# post-merge deploy: from 2026-10-23 to 2026-10-24 every deploy failed on ONNX Runtime's 27 MB WebGPU
# binary while every PR stayed green. 24 MiB leaves headroom, so a dependency that grows fails a PR.
max_file_bytes=$((24 * 1024 * 1024))
oversized="$(find packages/pwa/dist -type f -size "+${max_file_bytes}c" -printf '%s bytes  %p\n' | sort -rn)"
[[ -z ${oversized} ]] || {
  echo "❌ packages/pwa/dist has files over 24 MiB; Cloudflare Pages refuses any file over 25 MiB:" >&2
  printf '%s\n' "${oversized}" >&2
  exit 1
}
cmp packages/pwa/public/_headers packages/pwa/dist/_headers
cmp packages/pwa/public/_redirects packages/pwa/dist/_redirects

echo "✅ PWA static bundle and Pages headers are ready"
